#if defined(XAR_CK3_ENABLE_G2_MILITARY_PREPARATION_SUMMARY_PRIVATE_PROBE_V1)
bool InitializeMilitaryPreparationSummaryPrivateProbeV1(
    std::uintptr_t module_base) noexcept {
  xar::bridge::MilitaryPreparationSummaryEnvironmentV1 core{};
  core.observer_enabled = true;
  core.exact_build_admitted = true;
  core.admitted_executable_sha256 =
      xar::bridge::kMilitaryPreparationSummaryExecutableSha256V1;
  core.callback_context =
      &g_military_preparation_summary_private_probe_v1;
  core.read_frame =
      &xar::bridge::ReadMilitaryPreparationSummaryPrivateProbeFrameV1;

  xar::bridge::MilitaryPreparationSummaryBindingEnvironmentV1 binding{};
  binding.binding_enabled = true;
  binding.exact_build_admitted = true;
  binding.admitted_executable_sha256 =
      xar::bridge::kMilitaryPreparationSummaryExecutableSha256V1;
  binding.module_base = module_base;
  if (!xar::bridge::BindMilitaryPreparationSummaryV1(
          binding, g_military_preparation_summary_binding_v1, core)) {
    return false;
  }
  return xar::bridge::InstallMilitaryPreparationSummaryPrivateProbeV1(
      g_military_preparation_summary_private_probe_v1, core);
}

void DriveMilitaryPreparationSummaryPrivateProbeV1(
    const std::optional<xar::game::Snapshot> &snapshot,
    std::uint64_t revision) noexcept {
  auto &probe = g_military_preparation_summary_private_probe_v1;
  if (!probe.installed || probe.result_published) return;

  if (!g_military_preparation_summary_private_probe_in_flight_v1) {
    if (!probe.request_prepared) {
      if (!snapshot.has_value() || revision == 0 ||
          !snapshot->map_ready || !snapshot->paused ||
          !snapshot->has_played_character ||
          snapshot->played_character_id <= 0) {
        return;
      }
      const xar::bridge::MilitaryPreparationFrameIdentityV1 frame{
          revision, snapshot->date_raw, snapshot->played_character_id, 0,
          snapshot->paused};
      if (!xar::bridge::PrepareMilitaryPreparationSummaryPrivateProbeV1(
              probe, frame, revision)) {
        return;
      }
    }
    const auto submit = xar::ck3_11906::TrySubmitMainThreadQueryV1(
        g_main_thread_query_mailbox_v1,
        &xar::bridge::ExecuteMilitaryPreparationSummaryPrivateProbeV1,
        &probe, g_military_preparation_summary_private_probe_ticket_v1);
    g_military_preparation_summary_private_probe_last_submit_v1 =
        static_cast<std::uint32_t>(submit);
    if (submit ==
        xar::ck3_11906::MainThreadQuerySubmitResultV1::submitted) {
      g_military_preparation_summary_private_probe_in_flight_v1 = true;
    } else if (submit != xar::ck3_11906::MainThreadQuerySubmitResultV1::
                             paused_main_thread_not_observed &&
               submit != xar::ck3_11906::MainThreadQuerySubmitResultV1::
                             mailbox_busy &&
               submit != xar::ck3_11906::MainThreadQuerySubmitResultV1::
                             application_main_not_observed) {
      (void)xar::bridge::
          PublishMilitaryPreparationSummaryPrivateProbeFailureV1(
              probe, xar::bridge::
                         military_preparation_summary_failure_callbacks);
    }
  }
  if (!g_military_preparation_summary_private_probe_in_flight_v1) return;

  if (!xar::bridge::TryPublishMilitaryPreparationSummaryPrivateProbeMailboxV1(
          probe, g_main_thread_query_mailbox_v1,
          g_military_preparation_summary_private_probe_ticket_v1)) {
    return;
  }

  const auto state =
      g_main_thread_query_mailbox_v1.state.load(std::memory_order_acquire);
  auto terminal_result =
      xar::ck3_11906::MainThreadQueryWaitResultV1::ticket_mismatch;
  if (g_main_thread_query_mailbox_v1.published_sequence.load(
          std::memory_order_acquire) ==
      g_military_preparation_summary_private_probe_ticket_v1.sequence) {
    switch (state) {
    case xar::ck3_11906::MainThreadQueryMailboxStateV1::completed:
      terminal_result =
          xar::ck3_11906::MainThreadQueryWaitResultV1::completed;
      break;
    case xar::ck3_11906::MainThreadQueryMailboxStateV1::executor_failed:
      terminal_result =
          xar::ck3_11906::MainThreadQueryWaitResultV1::executor_failed;
      break;
    case xar::ck3_11906::MainThreadQueryMailboxStateV1::
        infrastructure_failed:
      terminal_result =
          xar::ck3_11906::MainThreadQueryWaitResultV1::infrastructure_failed;
      break;
    case xar::ck3_11906::MainThreadQueryMailboxStateV1::cancelled:
      terminal_result =
          xar::ck3_11906::MainThreadQueryWaitResultV1::cancelled;
      break;
    default:
      break;
    }
  }
  g_military_preparation_summary_private_probe_last_wait_v1 =
      static_cast<std::uint32_t>(terminal_result);
  (void)xar::ck3_11906::ReclaimMainThreadQueryV1(
      g_main_thread_query_mailbox_v1,
      g_military_preparation_summary_private_probe_ticket_v1);
  g_military_preparation_summary_private_probe_in_flight_v1 = false;
}
#endif

#if defined(XAR_CK3_ENABLE_G2_FACTION_TARGETING_ROW_ASYNC_PRIVATE_PROBE_V1)
std::string_view FactionTargetingRowAsyncStateNameV1(
    FactionTargetingRowAsyncStateV1 state) noexcept {
  switch (state) {
  case FactionTargetingRowAsyncStateV1::waiting_snapshot:
    return "waiting-snapshot";
  case FactionTargetingRowAsyncStateV1::query_queued:
    return "query-queued";
  case FactionTargetingRowAsyncStateV1::query_executing:
    return "query-executing";
  case FactionTargetingRowAsyncStateV1::awaiting_observer:
    return "awaiting-observer";
  case FactionTargetingRowAsyncStateV1::terminal:
    return "terminal";
  case FactionTargetingRowAsyncStateV1::blocked:
    return "blocked";
  }
  return "blocked";
}

bool ReadFactionTargetingRowCaptureAdmissionV1(
    void *context,
    xar::bridge::FactionTargetingRowCaptureAdmissionV1 &admission) noexcept {
  auto *mailbox = static_cast<xar::ck3_11906::MainThreadQueryMailboxV1 *>(
      context);
  const auto before =
      g_faction_targeting_row_admission_v1.generation.load(
          std::memory_order_acquire);
  if (mailbox == nullptr || before == 0 || (before & 1U) != 0 ||
      !mailbox->observed_stamp_read_success.load(std::memory_order_acquire)) {
    return false;
  }

  xar::bridge::FactionTargetingRowCaptureAdmissionV1 candidate{};
  candidate.proof_epoch =
      g_faction_targeting_row_admission_v1.proof_epoch.load(
          std::memory_order_relaxed);
  candidate.snapshot_revision =
      g_faction_targeting_row_admission_v1.snapshot_revision.load(
          std::memory_order_relaxed);
  candidate.date_raw =
      g_faction_targeting_row_admission_v1.date_raw.load(
          std::memory_order_relaxed);
  candidate.player_character_id =
      g_faction_targeting_row_admission_v1.player_character_id.load(
          std::memory_order_relaxed);
  candidate.player_targeting_faction_count =
      g_faction_targeting_row_admission_v1
          .player_targeting_faction_count.load(std::memory_order_relaxed);
  const auto after =
      g_faction_targeting_row_admission_v1.generation.load(
          std::memory_order_acquire);

  const auto owner_thread_id =
      mailbox->owner_thread_id.load(std::memory_order_acquire);
  const auto observed_thread_id =
      mailbox->observed_current_thread_id.load(std::memory_order_acquire);
  if (before != after || (after & 1U) != 0 || owner_thread_id == 0 ||
      observed_thread_id != owner_thread_id ||
      GetCurrentThreadId() != owner_thread_id ||
      mailbox->observed_tls_initialized.load(std::memory_order_acquire) == 0 ||
      mailbox->observed_tls_main_thread_marker.load(
          std::memory_order_acquire) == 0 ||
      !mailbox->observed_paused.load(std::memory_order_acquire) ||
      mailbox->observed_date_raw.load(std::memory_order_acquire) !=
          candidate.date_raw ||
      mailbox->pump_epochs.load(std::memory_order_acquire) <
          candidate.proof_epoch ||
      candidate.proof_epoch == 0 || candidate.snapshot_revision == 0 ||
      candidate.player_character_id == 0 ||
      candidate.player_targeting_faction_count < 0) {
    return false;
  }

  candidate.application_main_thread_id = owner_thread_id;
  candidate.paused = true;
  admission = candidate;
  return true;
}

void PublishFactionTargetingRowAdmissionV1(
    const xar::ck3_11906::CampaignRootContextMailboxContextV1 &query) noexcept {
  const auto generation =
      g_faction_targeting_row_admission_v1.generation.load(
          std::memory_order_relaxed);
  const auto write_generation =
      (generation & 1U) == 0 ? generation + 1 : generation + 2;
  g_faction_targeting_row_admission_v1.generation.store(
      write_generation, std::memory_order_release);
  g_faction_targeting_row_admission_v1.proof_epoch.store(
      query.execution_stamp.pump_epoch, std::memory_order_relaxed);
  g_faction_targeting_row_admission_v1.snapshot_revision.store(
      query.result.snapshot_revision, std::memory_order_relaxed);
  g_faction_targeting_row_admission_v1.date_raw.store(
      query.result.date_raw, std::memory_order_relaxed);
  g_faction_targeting_row_admission_v1.player_character_id.store(
      static_cast<std::uint32_t>(*query.result.player_character_id),
      std::memory_order_relaxed);
  g_faction_targeting_row_admission_v1.player_targeting_faction_count.store(
      *query.result.player_targeting_faction_count,
      std::memory_order_relaxed);
  g_faction_targeting_row_admission_v1.generation.store(
      write_generation + 1, std::memory_order_release);
}

void ResetFactionTargetingRowCampaignQueryV1(
    const xar::game::Snapshot &snapshot, std::uint64_t revision) noexcept {
  auto &query = g_faction_targeting_row_campaign_query_v1;
  query.mailbox = &g_main_thread_query_mailbox_v1;
  query.ticket = {};
  query.bindings = xar::ck3_11906::BindCurrentProcess(true);
  query.environment = xar::ck3_11906::BindCampaignRootNativeEnvironmentV1(
      reinterpret_cast<std::uintptr_t>(GetModuleHandleW(nullptr)), true);
  query.access = {};
  query.request = {};
  query.request.expected_snapshot_revision = revision;
  query.expected_snapshot = snapshot;
  query.completion =
      xar::ck3_11906::CampaignRootContextMailboxCompletionV1::not_executed;
  query.read_result = xar::game::ReadCampaignRootContextResultV1::unavailable;
  query.result = {};
  query.execution_stamp = {};
  query.executor_invocations = 0;
}

void PublishFactionTargetingRowTerminalV1(
    const xar::bridge::FactionTargetingRowObserverDiagnosticsV1 &observer) {
  g_faction_targeting_row_terminal_result_v1 =
      xar::bridge::ProbeFactionTargetingRowsV1(
          observer, g_faction_targeting_row_required_binding_v1);
  g_faction_targeting_row_terminal_published_v1 = true;
  g_faction_targeting_row_async_state_v1 =
      FactionTargetingRowAsyncStateV1::terminal;
}

void DriveFactionTargetingRowAsyncPrivateProbeV1(
    const xar::game::GameAdapter &game,
    const std::optional<xar::game::Snapshot> &snapshot,
    std::uint64_t revision) noexcept {
  if (g_faction_targeting_row_terminal_published_v1 ||
      g_faction_targeting_row_async_state_v1 ==
          FactionTargetingRowAsyncStateV1::blocked) {
    return;
  }

  if (g_faction_targeting_row_async_state_v1 ==
      FactionTargetingRowAsyncStateV1::awaiting_observer) {
    const auto observer =
        xar::bridge::ReadFactionTargetingRowObserverDiagnosticsV1(
            g_faction_targeting_row_observer_v1);
    const auto &capture = observer.observation;
    const auto exact_binding =
        capture.last_proof_epoch ==
            g_faction_targeting_row_required_binding_v1.proof_epoch &&
        capture.last_snapshot_revision ==
            g_faction_targeting_row_required_binding_v1.snapshot_revision &&
        capture.last_date_raw ==
            g_faction_targeting_row_required_binding_v1.date_raw &&
        capture.last_player_character_id ==
            g_faction_targeting_row_required_binding_v1.player_character_id;
    if (!observer.installed ||
        observer.failure_flags !=
            xar::bridge::faction_targeting_row_observer_failure_none) {
      PublishFactionTargetingRowTerminalV1(observer);
    } else if (capture.published_generation != 0 &&
               (capture.published_generation & 1U) == 0 && exact_binding) {
      PublishFactionTargetingRowTerminalV1(observer);
    }
    return;
  }

  auto &query = g_faction_targeting_row_campaign_query_v1;
  if (!g_faction_targeting_row_query_in_flight_v1) {
    if (!snapshot.has_value() || revision == 0 || !snapshot->map_ready ||
        !snapshot->paused || !snapshot->has_played_character ||
        !snapshot->played_character_alive ||
        snapshot->played_character_id <= 0) {
      return;
    }
    xar::game::Snapshot current{};
    if (!xar::game::ReadSnapshot(game, current) || current != *snapshot) {
      return;
    }
    ResetFactionTargetingRowCampaignQueryV1(current, revision);
    const auto submit = xar::ck3_11906::TrySubmitMainThreadQueryV1(
        g_main_thread_query_mailbox_v1,
        &xar::ck3_11906::ExecuteCampaignRootContextMailboxQueryV1, &query,
        query.ticket);
    g_faction_targeting_row_last_submit_v1 =
        static_cast<std::uint32_t>(submit);
    if (submit == xar::ck3_11906::MainThreadQuerySubmitResultV1::submitted) {
      g_faction_targeting_row_query_in_flight_v1 = true;
      g_faction_targeting_row_async_state_v1 =
          FactionTargetingRowAsyncStateV1::query_queued;
    } else if (
        submit != xar::ck3_11906::MainThreadQuerySubmitResultV1::
                      paused_main_thread_not_observed &&
        submit != xar::ck3_11906::MainThreadQuerySubmitResultV1::
                      mailbox_busy &&
        submit != xar::ck3_11906::MainThreadQuerySubmitResultV1::
                      application_main_not_observed) {
      g_faction_targeting_row_async_failure_v1 |= 1U;
      g_faction_targeting_row_async_state_v1 =
          FactionTargetingRowAsyncStateV1::blocked;
    }
  }
  if (!g_faction_targeting_row_query_in_flight_v1) return;

  if (g_main_thread_query_mailbox_v1.published_sequence.load(
          std::memory_order_acquire) != query.ticket.sequence) {
    return;
  }
  const auto mailbox_state =
      g_main_thread_query_mailbox_v1.state.load(std::memory_order_acquire);
  if (mailbox_state ==
      xar::ck3_11906::MainThreadQueryMailboxStateV1::queued) {
    g_faction_targeting_row_async_state_v1 =
        FactionTargetingRowAsyncStateV1::query_queued;
    return;
  }
  if (mailbox_state ==
      xar::ck3_11906::MainThreadQueryMailboxStateV1::executing) {
    g_faction_targeting_row_async_state_v1 =
        FactionTargetingRowAsyncStateV1::query_executing;
    return;
  }

  auto terminal_wait =
      xar::ck3_11906::MainThreadQueryWaitResultV1::ticket_mismatch;
  switch (mailbox_state) {
  case xar::ck3_11906::MainThreadQueryMailboxStateV1::completed:
    terminal_wait = xar::ck3_11906::MainThreadQueryWaitResultV1::completed;
    break;
  case xar::ck3_11906::MainThreadQueryMailboxStateV1::executor_failed:
    terminal_wait =
        xar::ck3_11906::MainThreadQueryWaitResultV1::executor_failed;
    break;
  case xar::ck3_11906::MainThreadQueryMailboxStateV1::cancelled:
    terminal_wait = xar::ck3_11906::MainThreadQueryWaitResultV1::cancelled;
    break;
  case xar::ck3_11906::MainThreadQueryMailboxStateV1::infrastructure_failed:
    terminal_wait =
        xar::ck3_11906::MainThreadQueryWaitResultV1::infrastructure_failed;
    break;
  default:
    return;
  }
  g_faction_targeting_row_last_wait_v1 =
      static_cast<std::uint32_t>(terminal_wait);

  bool completion_snapshot_stable = false;
  xar::game::Snapshot completion_snapshot{};
  if (terminal_wait ==
      xar::ck3_11906::MainThreadQueryWaitResultV1::completed) {
    completion_snapshot_stable =
        xar::game::ReadSnapshot(game, completion_snapshot) &&
        completion_snapshot == query.expected_snapshot;
  }
  const bool root_available =
      terminal_wait ==
          xar::ck3_11906::MainThreadQueryWaitResultV1::completed &&
      query.completion == xar::ck3_11906::
                              CampaignRootContextMailboxCompletionV1::
                                  completed &&
      completion_snapshot_stable &&
      query.result.status == xar::game::CampaignRootContextStatusV1::available &&
      query.result.readiness.same_frame_ready &&
      query.result.player_character_id.has_value() &&
      *query.result.player_character_id > 0 &&
      query.result.player_targeting_faction_count.has_value() &&
      *query.result.player_targeting_faction_count >= 0 &&
      query.execution_stamp.paused && query.execution_stamp.pump_epoch != 0;

  if (root_available) {
    g_faction_targeting_row_required_binding_v1 = {
        true, query.execution_stamp.pump_epoch,
        query.result.snapshot_revision, query.result.date_raw,
        static_cast<std::uint32_t>(*query.result.player_character_id)};
    PublishFactionTargetingRowAdmissionV1(query);
  } else {
    g_faction_targeting_row_async_failure_v1 |=
        terminal_wait ==
                xar::ck3_11906::MainThreadQueryWaitResultV1::completed
            ? 4U
            : 2U;
  }

  const auto reclaimed = xar::ck3_11906::ReclaimMainThreadQueryV1(
      g_main_thread_query_mailbox_v1, query.ticket);
  g_faction_targeting_row_last_reclaim_v1 =
      static_cast<std::uint32_t>(reclaimed);
  g_faction_targeting_row_query_in_flight_v1 = false;
  if (reclaimed !=
      xar::ck3_11906::MainThreadQueryReclaimResultV1::reclaimed) {
    g_faction_targeting_row_async_failure_v1 |= 8U;
  }
  g_faction_targeting_row_async_state_v1 =
      root_available &&
              reclaimed ==
                  xar::ck3_11906::MainThreadQueryReclaimResultV1::reclaimed
          ? FactionTargetingRowAsyncStateV1::awaiting_observer
          : FactionTargetingRowAsyncStateV1::blocked;
}
#endif

#if defined(XAR_CK3_ENABLE_G2_FACTION_GIFT_MITIGATION_ASYNC_PRIVATE_GLUE_V1)
bool SelectFactionGiftMitigationCandidateV1(
    std::uint32_t &source_faction_id,
    std::uint32_t &recipient_character_id) noexcept {
  source_faction_id = 0;
  recipient_character_id = 0;
  const auto &rows = g_faction_targeting_row_terminal_result_v1;
  const auto &root = g_faction_targeting_row_campaign_query_v1.result;
  if (rows.terminal !=
          xar::bridge::FactionTargetingRowProbeTerminalV1::ready ||
      !root.readiness.same_frame_ready ||
      !root.player_character_id.has_value() ||
      *root.player_character_id <= 0) {
    return false;
  }
  auto direct = root.direct_landed_vassal_character_ids;
  std::sort(direct.begin(), direct.end());
  const auto eligible = [&](std::uint32_t character_id) noexcept {
    return character_id != 0 &&
           character_id !=
               static_cast<std::uint32_t>(*root.player_character_id) &&
           std::binary_search(direct.begin(), direct.end(),
                              static_cast<std::int32_t>(character_id));
  };
  for (std::size_t index = 0; index < rows.faction_count; ++index) {
    const auto &row = rows.factions[index];
    if (row.target_character_id !=
        static_cast<std::uint32_t>(*root.player_character_id)) {
      continue;
    }
    if (row.leader_present && eligible(row.leader_character_id)) {
      source_faction_id = row.faction_id;
      recipient_character_id = row.leader_character_id;
      return true;
    }
    for (std::size_t member = 0;
         member < row.character_member_count; ++member) {
      if (!eligible(row.character_member_ids[member])) continue;
      source_faction_id = row.faction_id;
      recipient_character_id = row.character_member_ids[member];
      return true;
    }
  }
  return false;
}

void DriveFactionGiftMitigationAsyncPrivateGlueV1(
    const std::optional<xar::game::Snapshot> &snapshot,
    std::uint64_t revision) noexcept {
  if (g_faction_gift_mitigation_terminal_published_v1 ||
      !g_faction_targeting_row_terminal_published_v1) {
    return;
  }
  auto &query = g_faction_gift_mitigation_async_query_v1;
  if (!g_faction_gift_mitigation_query_in_flight_v1) {
    std::uint32_t source_faction_id = 0;
    std::uint32_t recipient_character_id = 0;
    if (!snapshot.has_value() || revision == 0 || !snapshot->paused ||
        !snapshot->map_ready || !snapshot->has_played_character ||
        snapshot->played_character_id <= 0 ||
        snapshot->date_raw !=
            g_faction_targeting_row_terminal_result_v1.observed_binding
                .date_raw ||
        revision != g_faction_targeting_row_terminal_result_v1
                        .observed_binding.snapshot_revision ||
        !SelectFactionGiftMitigationCandidateV1(
            source_faction_id, recipient_character_id)) {
      query = {};
      query.completion = xar::ck3_11906::
          FactionGiftMitigationAsyncCompletionV1::unavailable;
      query.failure_flags = xar::ck3_11906::
          faction_gift_async_failure_recipient;
      g_faction_gift_mitigation_terminal_published_v1 = true;
      return;
    }
    query = {};
    query.mailbox = &g_main_thread_query_mailbox_v1;
    query.bindings = xar::ck3_11906::BindCurrentProcess(true);
    query.module_base =
        reinterpret_cast<std::uintptr_t>(GetModuleHandleW(nullptr));
    query.expected_snapshot = *snapshot;
    query.targeting_rows = g_faction_targeting_row_terminal_result_v1;
    query.direct_landed_vassal_character_ids =
        g_faction_targeting_row_campaign_query_v1.result
            .direct_landed_vassal_character_ids;
    std::sort(query.direct_landed_vassal_character_ids.begin(),
              query.direct_landed_vassal_character_ids.end());
    query.source_faction_id = source_faction_id;
    query.recipient_character_id = recipient_character_id;
    const auto submit = xar::ck3_11906::TrySubmitMainThreadQueryV1(
        g_main_thread_query_mailbox_v1,
        &xar::ck3_11906::ExecuteFactionGiftMitigationAsyncMailboxV1,
        &query, query.ticket);
    g_faction_gift_mitigation_last_submit_v1 =
        static_cast<std::uint32_t>(submit);
    if (submit ==
        xar::ck3_11906::MainThreadQuerySubmitResultV1::submitted) {
      g_faction_gift_mitigation_query_in_flight_v1 = true;
    }
    return;
  }
  if (g_main_thread_query_mailbox_v1.published_sequence.load(
          std::memory_order_acquire) != query.ticket.sequence) {
    return;
  }
  const auto state = g_main_thread_query_mailbox_v1.state.load(
      std::memory_order_acquire);
  if (state == xar::ck3_11906::MainThreadQueryMailboxStateV1::queued ||
      state == xar::ck3_11906::MainThreadQueryMailboxStateV1::executing) {
    return;
  }
  xar::ck3_11906::MainThreadQueryWaitResultV1 wait =
      xar::ck3_11906::MainThreadQueryWaitResultV1::ticket_mismatch;
  if (state == xar::ck3_11906::MainThreadQueryMailboxStateV1::completed) {
    wait = xar::ck3_11906::MainThreadQueryWaitResultV1::completed;
  } else if (state == xar::ck3_11906::
                          MainThreadQueryMailboxStateV1::executor_failed) {
    wait = xar::ck3_11906::MainThreadQueryWaitResultV1::executor_failed;
  } else if (state == xar::ck3_11906::
                          MainThreadQueryMailboxStateV1::cancelled) {
    wait = xar::ck3_11906::MainThreadQueryWaitResultV1::cancelled;
  } else if (state == xar::ck3_11906::
                          MainThreadQueryMailboxStateV1::infrastructure_failed) {
    wait = xar::ck3_11906::MainThreadQueryWaitResultV1::infrastructure_failed;
  } else {
    return;
  }
  g_faction_gift_mitigation_last_wait_v1 =
      static_cast<std::uint32_t>(wait);
  const auto reclaim = xar::ck3_11906::ReclaimMainThreadQueryV1(
      g_main_thread_query_mailbox_v1, query.ticket);
  g_faction_gift_mitigation_last_reclaim_v1 =
      static_cast<std::uint32_t>(reclaim);
  g_faction_gift_mitigation_query_in_flight_v1 = false;
  if (wait != xar::ck3_11906::MainThreadQueryWaitResultV1::completed ||
      reclaim != xar::ck3_11906::
                     MainThreadQueryReclaimResultV1::reclaimed) {
    query.completion = xar::ck3_11906::
        FactionGiftMitigationAsyncCompletionV1::unavailable;
    query.failure_flags |=
        xar::ck3_11906::faction_gift_async_failure_frame;
  }
  g_faction_gift_mitigation_terminal_published_v1 = true;
}
#endif

#if defined(XAR_CK3_ENABLE_G2_COUNCIL_COMPOSITION_STEWARD_CANDIDATES_PRIVATE_PROBE_V1)
bool InitializeCouncilCompositionStewardCandidatesPrivateProbeV1(
    std::uintptr_t module_base) noexcept {
  auto &probe =
      g_council_composition_steward_candidates_private_probe_v1;
  if (!xar::bridge::
          ConfigureCouncilCompositionStewardCandidatesPrivateProbeTransportV1(
              probe, g_main_thread_query_mailbox_v1,
              xar::ck3_11906::BindCurrentProcess(true),
              g_council_composition_steward_candidates_binding_v1)) {
    return false;
  }

  xar::ck3_11906::CouncilCompositionStewardCandidatesEnvironmentV1 core{};
  auto access =
      xar::bridge::CouncilCompositionStewardCandidatesProbeAccessV1(probe);
  xar::ck3_11906::CouncilCompositionStewardCandidatesBindingEnvironmentV1
      binding{};
  binding.binding_enabled = true;
  binding.exact_build_admitted = true;
  binding.admitted_executable_sha256 =
      xar::ck3_11906::
          kCouncilCompositionStewardCandidatesReaderExecutableSha256V1;
  binding.module_base = module_base;
  if (!xar::ck3_11906::BindCouncilCompositionStewardCandidatesV1(
          binding, g_council_composition_steward_candidates_binding_v1,
          core, access)) {
    return false;
  }
  return xar::bridge::
      InstallCouncilCompositionStewardCandidatesPrivateProbeV1(
          probe, core, access);
}

void DriveCouncilCompositionStewardCandidatesPrivateProbeV1(
    const std::optional<xar::game::Snapshot> &snapshot,
    std::uint64_t revision) noexcept {
  auto &probe =
      g_council_composition_steward_candidates_private_probe_v1;
  if (!probe.installed || probe.result_published) return;

  if (!g_council_composition_steward_candidates_private_probe_in_flight_v1) {
    if (!probe.request_prepared) {
      if (!snapshot.has_value() || revision == 0 ||
          !snapshot->map_ready || !snapshot->paused ||
          !snapshot->has_played_character ||
          !snapshot->played_character_alive ||
          snapshot->played_character_id <= 0) {
        return;
      }
      if (!xar::bridge::
              PrepareCouncilCompositionStewardCandidatesPrivateProbeV1(
                  probe, *snapshot, revision, revision)) {
        return;
      }
    }
    const auto submit = xar::ck3_11906::TrySubmitMainThreadQueryV1(
        g_main_thread_query_mailbox_v1,
        &xar::bridge::
            ExecuteCouncilCompositionStewardCandidatesPrivateProbeV1,
        &probe, probe.ticket);
    g_council_composition_steward_candidates_private_probe_last_submit_v1 =
        static_cast<std::uint32_t>(submit);
    if (submit ==
        xar::ck3_11906::MainThreadQuerySubmitResultV1::submitted) {
      g_council_composition_steward_candidates_private_probe_in_flight_v1 =
          true;
    } else if (
        submit != xar::ck3_11906::MainThreadQuerySubmitResultV1::
                      paused_main_thread_not_observed &&
        submit != xar::ck3_11906::MainThreadQuerySubmitResultV1::
                      mailbox_busy &&
        submit != xar::ck3_11906::MainThreadQuerySubmitResultV1::
                      application_main_not_observed) {
      (void)xar::bridge::
          PublishCouncilCompositionStewardCandidatesPrivateProbeFailureV1(
              probe,
              xar::game::CouncilCompositionStewardCandidatesFailureV1::
                  application_main_thread_required);
    }
  }
  if (!g_council_composition_steward_candidates_private_probe_in_flight_v1) {
    return;
  }

  if (!xar::bridge::
          TryPublishCouncilCompositionStewardCandidatesPrivateProbeMailboxV1(
              probe, g_main_thread_query_mailbox_v1, probe.ticket)) {
    return;
  }

  const auto state =
      g_main_thread_query_mailbox_v1.state.load(std::memory_order_acquire);
  auto terminal_result =
      xar::ck3_11906::MainThreadQueryWaitResultV1::ticket_mismatch;
  if (g_main_thread_query_mailbox_v1.published_sequence.load(
          std::memory_order_acquire) == probe.ticket.sequence) {
    switch (state) {
    case xar::ck3_11906::MainThreadQueryMailboxStateV1::completed:
      terminal_result =
          xar::ck3_11906::MainThreadQueryWaitResultV1::completed;
      break;
    case xar::ck3_11906::MainThreadQueryMailboxStateV1::executor_failed:
      terminal_result =
          xar::ck3_11906::MainThreadQueryWaitResultV1::executor_failed;
      break;
    case xar::ck3_11906::MainThreadQueryMailboxStateV1::
        infrastructure_failed:
      terminal_result =
          xar::ck3_11906::MainThreadQueryWaitResultV1::infrastructure_failed;
      break;
    case xar::ck3_11906::MainThreadQueryMailboxStateV1::cancelled:
      terminal_result =
          xar::ck3_11906::MainThreadQueryWaitResultV1::cancelled;
      break;
    default:
      break;
    }
  }
  g_council_composition_steward_candidates_private_probe_last_wait_v1 =
      static_cast<std::uint32_t>(terminal_result);
  (void)xar::ck3_11906::ReclaimMainThreadQueryV1(
      g_main_thread_query_mailbox_v1, probe.ticket);
  g_council_composition_steward_candidates_private_probe_in_flight_v1 =
      false;
}
#endif

#if defined(XAR_CK3_ENABLE_G2_DOMAIN_CONSTRUCTION_CANDIDATE_OBSERVER_V1)
bool ReadDomainConstructionCandidateCaptureAdmissionV1(
    void *context,
    xar::bridge::DomainConstructionCandidateCaptureAdmissionV1
        &admission) noexcept {
  auto *mailbox = static_cast<xar::ck3_11906::MainThreadQueryMailboxV1 *>(
      context);
  if (mailbox == nullptr ||
      !mailbox->observed_stamp_read_success.load(std::memory_order_acquire)) {
    return false;
  }
  const auto owner_thread_id =
      mailbox->owner_thread_id.load(std::memory_order_acquire);
  const auto observed_thread_id =
      mailbox->observed_current_thread_id.load(std::memory_order_acquire);
  const auto proof_epoch = mailbox->pump_epochs.load(std::memory_order_acquire);
  if (owner_thread_id == 0 || observed_thread_id != owner_thread_id ||
      GetCurrentThreadId() != owner_thread_id ||
      mailbox->observed_tls_initialized.load(std::memory_order_acquire) == 0 ||
      mailbox->observed_tls_main_thread_marker.load(
          std::memory_order_acquire) == 0 ||
      mailbox->paused_owner_verified_pump_epochs.load(
          std::memory_order_acquire) <
          xar::ck3_11906::kMainThreadQueryMinimumOwnerVerifiedPumpEpochs ||
      proof_epoch == 0 || mailbox->module_base == 0) {
    return false;
  }

  const auto read_current = [](std::uintptr_t address, void *output,
                               std::size_t size) noexcept {
    SIZE_T read = 0;
    return address != 0 && output != nullptr && size != 0 &&
        ReadProcessMemory(GetCurrentProcess(),
                          reinterpret_cast<const void *>(address), output,
                          size, &read) != FALSE &&
        read == size;
  };
  std::uintptr_t jomini_state = 0;
  std::uintptr_t game_state = 0;
  if (!read_current(mailbox->module_base +
                        xar::ck3_11906::kJominiStateSlotRva,
                    &jomini_state, sizeof(jomini_state)) ||
      !read_current(mailbox->module_base +
                        xar::ck3_11906::kGameStateSlotRva,
                    &game_state, sizeof(game_state)) ||
      jomini_state == 0 || game_state == 0 ||
      jomini_state != mailbox->observed_jomini_state.load(
                           std::memory_order_acquire) ||
      game_state != mailbox->observed_game_state.load(
                        std::memory_order_acquire)) {
    return false;
  }
  std::uint8_t paused = 0;
  std::int32_t date_raw = 0;
  if (!read_current(jomini_state + xar::ck3_11906::kJominiPausedOffset,
                    &paused, sizeof(paused)) ||
      !read_current(game_state + xar::ck3_11906::kGameStateDateRawOffset,
                    &date_raw, sizeof(date_raw)) ||
      date_raw != mailbox->observed_date_raw.load(std::memory_order_acquire)) {
    return false;
  }
  admission.application_main_thread_id = owner_thread_id;
  admission.paused = paused != 0;
  admission.proof_epoch = proof_epoch;
  admission.date_raw = date_raw;
  return true;
}
#endif

