bool IsPipeName(const wchar_t *value, DWORD length) noexcept {
  constexpr wchar_t prefix[] = L"\\\\.\\pipe\\";
  constexpr DWORD prefix_length =
      static_cast<DWORD>((sizeof(prefix) / sizeof(prefix[0])) - 1U);
  if (length <= prefix_length || length >= kPipeNameCapacity) {
    return false;
  }
  for (DWORD index = 0; index < prefix_length; ++index) {
    if (value[index] != prefix[index]) {
      return false;
    }
  }
  return true;
}

std::string Number(std::uint64_t value) {
  std::array<char, 32> buffer{};
  const auto result =
      std::to_chars(buffer.data(), buffer.data() + buffer.size(), value);
  if (result.ec != std::errc{}) {
    return "0";
  }
  return std::string(buffer.data(), result.ptr);
}

std::string SignedNumber(std::int64_t value) {
  std::array<char, 32> buffer{};
  const auto result =
      std::to_chars(buffer.data(), buffer.data() + buffer.size(), value);
  if (result.ec != std::errc{}) {
    return "0";
  }
  return std::string(buffer.data(), result.ptr);
}

void AppendJsonString(std::string &result, std::string_view value) {
  constexpr char hex[] = "0123456789ABCDEF";
  result += '"';
  for (const unsigned char character : value) {
    if (character == '"' || character == '\\') {
      result += '\\';
      result += static_cast<char>(character);
    } else if (character < 0x20U) {
      result += "\\u00";
      result += hex[(character >> 4U) & 0x0FU];
      result += hex[character & 0x0FU];
    } else {
      result += static_cast<char>(character);
    }
  }
  result += '"';
}

void AppendNamedPath583String(
    std::string &result, std::string_view name,
    const xar::bridge::NamedPath583StringDiagnosticsV1 &value) {
  result += ",\"";
  result += name;
  result += "\":{\"object\":";
  result += Number(value.object);
  result += ",\"effective_data\":";
  result += Number(value.effective_data);
  result += ",\"length\":";
  result += Number(value.length);
  result += ",\"capacity\":";
  result += Number(value.capacity);
  result += ",\"word0\":";
  result += Number(value.word0);
  result += ",\"word1\":";
  result += Number(value.word1);
  result += ",\"null_result\":";
  result += value.null_result ? "true" : "false";
  result += ",\"read_fault\":";
  result += value.read_fault ? "true" : "false";
  result += '}';
}

void AppendPdxPaths583Table(
    std::string &result, std::string_view name,
    const xar::bridge::PdxPaths583TableDiagnosticsV1 &value) {
  result += ",\"";
  result += name;
  result += "\":{\"map\":";
  result += Number(value.map);
  result += ",\"rows\":";
  result += Number(value.rows);
  result += ",\"count\":";
  result += Number(value.count);
  result += ",\"mask\":";
  result += Number(value.mask);
  result += ",\"max_probe\":";
  result += Number(value.max_probe);
  result += ",\"id_583_present\":";
  result += value.id_583_present ? "true" : "false";
  result += ",\"id_583_row\":";
  result += Number(value.id_583_row);
  result += ",\"read_fault\":";
  result += value.read_fault ? "true" : "false";
  result += '}';
}

