std::string RenderNativePrivateFrameV1(const xar::game::GameAdapter &game,
    std::string frame) {
  if (xar::game::IsCk3_12004Descriptor(game.descriptor()))
    return xar::game::Render12004BuildIdentity(std::move(frame), game.descriptor());
  return xar::game::IsReviewedCrozierAdapter(game)
      ? xar::ck3_12002::RenderQueryBuildIdentity(std::move(frame)) : frame;
}

std::string IdentityFrame() {
  const auto selected = xar::game::SelectCurrentProcessAdapter();
  const auto &descriptor = selected != nullptr && selected->enabled()
      ? selected->descriptor() : xar::game::PreferredAdapterDescriptor();
  std::string result =
      "{\"bridge\":\"xar_ck3_bridge\",\"bridge_version\":\"";
  result += XAR_BRIDGE_VERSION;
  result += "\",\"protocol_version\":1,\"architecture\":"
            "\"x86_64-windows-msvc\",\"expected_ck3_version\":";
  AppendJsonString(result, descriptor.game_version);
  result += ",\"expected_ck3_sha256\":";
  AppendJsonString(result, descriptor.executable_sha256);
  result += ",\"game_adapter_id\":";
  AppendJsonString(result, descriptor.adapter_id);
  result += '}';
  return result;
}

struct CheckpointSubmission {
  std::uint64_t sequence = 0;
  std::int32_t date_raw = 0;
  std::string_view save_name;
};

struct SnapshotPublishDiagnostics {
  std::string_view status = "not_attempted";
  std::uint64_t revision = 0;
  std::size_t payload_bytes = 0;
};

std::string HelloFrame(const xar::game::GameAdapter &game,
                       std::uint64_t connection_generation) {
  const auto &descriptor = game.descriptor();
  std::string result =
      "{\"type\":\"hello\",\"protocol_version\":1,\"bridge_version\":\"";
  result += XAR_BRIDGE_VERSION;
  result += "\",\"pid\":";
  result += Number(GetCurrentProcessId());
  result +=
      ",\"session_generation\":0,\"connection_generation\":";
  result += Number(connection_generation);
  result += ",\"architecture\":\"x86_64-windows-msvc\","
      "\"expected_ck3_version\":";
  AppendJsonString(result, descriptor.game_version);
  result += ",\"expected_ck3_sha256\":";
  AppendJsonString(result, descriptor.executable_sha256);
  result += ",\"game_adapter_id\":";
  AppendJsonString(result, descriptor.adapter_id);
  result += ",\"game_adapter_status\":";
  AppendJsonString(result, game.enabled() ? "ready" : "unsupported_build");
  result += ",\"ck3_build_match\":";
  result += game.enabled() ? "true" : "false";
  result += ",\"capabilities\":[\"bridge.identity\",\"bridge.heartbeat\","
            "\"bridge.ping\"";
  if (game.enabled()) {
    for (const auto capability : descriptor.capabilities) {
      result += ',';
      AppendJsonString(result, capability);
    }
  }
#if defined(XAR_CK3_ENABLE_PLAYER_CONTROL_PRIVATE_V1)
  // This capability describes only the closed typed partial source query.
  // It never advertises switch readiness or creates a stock-action admission.
  if(game.enabled() && descriptor.game_version==xar::ck3_12003::kGameVersion &&
      descriptor.executable_sha256==xar::ck3_12003::kExecutableSha256) {
    result += ',';
    AppendJsonString(result,xar::ck3_12003::kPlayerControlV1Capability);
  }
#endif
  result += "]}";
  return result;
}

// Retain only the real R0054 failed command paths. The pipe worker owns
// these records and publishes checkpoints before potentially blocking calls.
struct CommandEntryTraceV1 {
  std::string request_id;
  std::string frame_type;
  std::string parsed_step;
  std::string adapter_id;
  const char *stage = "not_received";
  const char *parse_kind = "not_parsed";
  const char *dispatch_route = "not_reached";
  std::uint64_t monotonic_ms = 0;
  bool type_parsed = false;
  bool request_id_parsed = false;
  bool step_parsed = false;
  bool handler_entered = false;
  std::int64_t submit_result = -1;
  std::int64_t call_result = -1;
  std::int64_t typed_query_kind = -1;
  std::string reply_request_id;
  std::string reply_type;
  bool reply_write_success = false;
};

struct CommandEntryTracesV1 {
  CommandEntryTraceV1 timeline{};
  CommandEntryTraceV1 war_termination_options{};
  CommandEntryTraceV1 war_termination_terms{};
  CommandEntryTraceV1 faction_gift_query{};
};

void AppendCommandEntryTraceV1(std::string &result,
                              const CommandEntryTraceV1 &trace) {
  result += "{\"request_id\":";
  AppendJsonString(result, trace.request_id);
  result += ",\"frame_type\":";
  AppendJsonString(result, trace.frame_type);
  result += ",\"parsed_step\":";
  AppendJsonString(result, trace.parsed_step);
  result += ",\"adapter_id\":";
  AppendJsonString(result, trace.adapter_id);
  result += ",\"typed_query_kind\":" + SignedNumber(trace.typed_query_kind);
  result += ",\"stage\":";
  AppendJsonString(result, trace.stage);
  result += ",\"parse_kind\":";
  AppendJsonString(result, trace.parse_kind);
  result += ",\"dispatch_route\":";
  AppendJsonString(result, trace.dispatch_route);
  result += ",\"monotonic_ms\":" + Number(trace.monotonic_ms);
  result += ",\"type_parsed\":";
  result += trace.type_parsed ? "true" : "false";
  result += ",\"request_id_parsed\":";
  result += trace.request_id_parsed ? "true" : "false";
  result += ",\"step_parsed\":";
  result += trace.step_parsed ? "true" : "false";
  result += ",\"handler_entered\":";
  result += trace.handler_entered ? "true" : "false";
  result += ",\"submit_result\":" + SignedNumber(trace.submit_result);
  result += ",\"call_result\":" + SignedNumber(trace.call_result);
  result += ",\"reply_request_id\":";
  AppendJsonString(result, trace.reply_request_id);
  result += ",\"reply_type\":";
  AppendJsonString(result, trace.reply_type);
  result += ",\"reply_write_success\":";
  result += trace.reply_write_success ? "true" : "false";
  result += "}";
}

