std::string ObservedHeirMarriageMaterialFrameV1(
    std::string_view request_id,
    const xar::bridge::ObservedHeirMarriagePendingV1 &pending,
    std::uint64_t post_revision,
    xar::bridge::ObservedHeirMarriageMaterialStatusV1 material,
    bool cold_recovery,
    const xar::bridge::MarriageOutboundPendingSnapshotV1 *outbound_pending,
    std::string_view step = kObservedFirstHeirMarriageResultStepV1,
    bool gone_unmaterialized = false,
    const xar::ck3_12003::FamilyTerminalEventsSnapshotV1 *terminal_events = nullptr) {
  const char *status = gone_unmaterialized ? "gone_unmaterialized" : "pending";
  if (material ==
      xar::bridge::ObservedHeirMarriageMaterialStatusV1::marriage)
    status = "marriage";
  if (material ==
      xar::bridge::ObservedHeirMarriageMaterialStatusV1::betrothal)
    status = "betrothal";
  if (material == xar::bridge::ObservedHeirMarriageMaterialStatusV1::refused)
    status = "refused";
  if (material == xar::bridge::ObservedHeirMarriageMaterialStatusV1::invalidated)
    status = "invalidated";
  if (material ==
      xar::bridge::ObservedHeirMarriageMaterialStatusV1::accepted_pending)
    status = "accepted_pending";
  std::string result =
      "{\"type\":\"command_result\",\"protocol_version\":1,\"request_id\":";
  AppendJsonString(result, request_id);
  result += ",\"ok\":true,\"result\":{\"step\":";
  AppendJsonString(result, step);
  result += ",\"accepted\":true,\"private_build\":true,\"advertised\":false,"
            "\"status\":";
  AppendJsonString(result, status);
  result += ",\"material_result\":";
  result += material ==
                    xar::bridge::ObservedHeirMarriageMaterialStatusV1::marriage ||
                    material == xar::bridge::ObservedHeirMarriageMaterialStatusV1::betrothal
                ? "true" : "false";
  result += ",\"cold_recovery\":";
  result += cold_recovery ? "true" : "false";
  result += ",\"pre_native_revision\":";
  result += Number(pending.pre_native_revision);
  result += ",\"post_native_revision\":";
  result += Number(post_revision);
  result += ",\"heir_character_id\":";
  result += SignedNumber(pending.heir_character_id);
  result += ",\"candidate_character_id\":";
  result += SignedNumber(pending.candidate_character_id);
  result += ",\"recipient_character_id\":";
  result += SignedNumber(pending.recipient_character_id);
  result += ",\"matrilineal_option_selected\":";
  result += pending.matrilineal_option_selected ? "true" : "false";
  result += ",\"fulfill_existing_betrothal\":";
  result += pending.fulfill_existing_betrothal ? "true" : "false";
  if (gone_unmaterialized) {
    result += ",\"proposal_disposition_source\":\"native_outbound_and_bilateral_pair\",\"terminal_cause_available\":false,\"terminal_cause\":\"not_observed\"";
  }
  if (terminal_events != nullptr) {
    result += ",\"retained_player_event_queue_available\":";
    result += terminal_events->available ? "true" : "false";
    result += ",\"retained_player_event_queue_read_complete\":";
    result += terminal_events->queue_read_complete ? "true" : "false";
    result += ",\"retained_player_event_queue_stable\":";
    result += terminal_events->queue_stable ? "true" : "false";
    result += ",\"retained_player_event_queue_count\":";
    result += SignedNumber(terminal_events->queue_count);
    result += ",\"retained_original_role_letter_count\":";
    result += Number(terminal_events->matched_count);
    result += ",\"retained_original_role_letter_kind\":";
    AppendJsonString(result, xar::ck3_12003::FamilyTerminalEventKindNameV1(terminal_events->kind));
    result += ",\"retained_player_event_unavailable_reason\":";
    AppendJsonString(result, xar::ck3_12003::FamilyTerminalEventFailureNameV1(terminal_events->failure));
  }
  if (cold_recovery) {
    result += ",\"outbound_pending_state\":";
    const char *outbound_state =
        material == xar::bridge::ObservedHeirMarriageMaterialStatusV1::pending
            ? "unavailable"
            : "not_applicable";
    if (outbound_pending != nullptr) {
      switch (outbound_pending->state) {
      case xar::bridge::MarriageOutboundPendingStateV1::active:
        outbound_state = "active";
        break;
      case xar::bridge::MarriageOutboundPendingStateV1::absent:
        outbound_state = "absent";
        break;
      case xar::bridge::MarriageOutboundPendingStateV1::ambiguous:
        outbound_state = "ambiguous";
        break;
      }
    }
    AppendJsonString(result, outbound_state);
    result += ",\"outbound_pending_id\":";
    result += outbound_pending != nullptr &&
                      outbound_pending->state ==
                          xar::bridge::MarriageOutboundPendingStateV1::active
                  ? SignedNumber(outbound_pending->pending_id)
                  : "null";
    result += ",\"outbound_pending_age_days\":";
    result += outbound_pending != nullptr &&
                      outbound_pending->state ==
                          xar::bridge::MarriageOutboundPendingStateV1::active
                  ? SignedNumber(outbound_pending->age_days)
                  : "null";
    result += ",\"outbound_pending_ai_reply_cutoff_days\":";
    result += outbound_pending != nullptr &&
                      outbound_pending->state ==
                          xar::bridge::MarriageOutboundPendingStateV1::active
                  ? SignedNumber(outbound_pending->ai_reply_cutoff_days)
                  : "null";
  }
  result += "}}";
  return result;
}

